/// The writer: the bytes of its record, as this build lays it out (`SIZE` long).
pub fn as_bytes(row: &Row) -> &[u8] {
    // SAFETY: a repr(C) record of plain numbers, the padding written as named zero bytes.
    unsafe { core::slice::from_raw_parts(row as *const Row as *const u8, SIZE) }
}
